/**
 * Regenerates the frozen compatibility-disabled parity artifact.
 *
 * Every value written here is OBTAINED from real SDK code, never hand-authored: the
 * artifact is only meaningful as a baseline if a behavior change moves it.
 *
 * Run after `npm run build --workspace=packages/sdk`:
 *   node test/fixtures/generate-copilot-compat-parity.mjs
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadAgentFiles, parseAgentFrontmatter } from "../../dist/agent-loader.js";
import { SessionManager, inheritsAppDefaults } from "../../dist/session-manager.js";
import { buildCompatSessionConfigFragment } from "../../dist/copilot-compat.js";

const fixturesDir = path.dirname(fileURLToPath(import.meta.url));
const fixtureAgentsDir = path.join(fixturesDir, "copilot-compat-plugin", "agents");
const artifactPath = path.join(fixturesDir, "copilot-compat-disabled-parity.json");

// ─── Parsed frontmatter, compatibility disabled ─────────────────

const parsedFrontmatter = {};
for (const filename of fs.readdirSync(fixtureAgentsDir).sort()) {
    if (!filename.endsWith(".agent.md")) continue;
    const content = fs.readFileSync(path.join(fixtureAgentsDir, filename), "utf-8");
    parsedFrontmatter[filename] = parseAgentFrontmatter(content).meta;
}

const loadedAgents = loadAgentFiles(fixtureAgentsDir)
    .map((agent) => ({
        name: agent.name,
        tools: agent.tools ?? null,
        agents: agent.agents ?? null,
        skills: agent.skills ?? null,
    }))
    .sort((left, right) => left.name.localeCompare(right.name));

// ─── Serialized session config, compatibility disabled ──────────

const baseSessionConfig = { model: "openai:gpt-5", toolNames: ["read", "write_file"] };
const serializedSessionConfig = { ...baseSessionConfig, ...buildCompatSessionConfigFragment(undefined) };

// ─── Resolved tool list AND order, via the real resolver ────────

const frameworkDefaultToolNames = ["view", "grep"];
const appDefaultToolNames = ["write_file", "view"];
const agentDeclaredToolNames = ["read", "grep", "execute"];

const sessionManager = new SessionManager(undefined, null, {
    frameworkBaseToolNames: frameworkDefaultToolNames,
    appDefaultToolNames,
});

const serializableConfig = { toolNames: agentDeclaredToolNames };

// Real precedence decision (session-manager.ts:956) rather than an assumed `true`.
const appDefaultsInherited = inheritsAppDefaults(
    { frameworkBaseToolNames: frameworkDefaultToolNames, appDefaultToolNames },
    serializableConfig,
);

const inheritedToolNames = Array.from(new Set([
    ...frameworkDefaultToolNames,
    ...(appDefaultsInherited ? appDefaultToolNames : []),
    ...agentDeclaredToolNames,
]));

// Registered as worker-registry tools so the real `_resolveTools()` does the dedupe and
// ordering; a name with no registered tool is dropped, exactly as in production.
const toolRegistry = new Map();
for (const name of inheritedToolNames) toolRegistry.set(name, { name });
sessionManager.setToolRegistry(toolRegistry);

const resolvedTools = sessionManager["_resolveTools"](undefined, { toolNames: inheritedToolNames });
const resolvedToolNamesInOrder = resolvedTools.map((tool) => tool.name);

// ─── Emit ───────────────────────────────────────────────────────

const artifact = {
    $comment: [
        "GENERATED by test/fixtures/generate-copilot-compat-parity.mjs — do not hand-edit.",
        "Frozen baseline of real SDK output with Copilot CLI compatibility DISABLED.",
        "A diff here means disabled-path behavior moved and must be justified.",
    ],
    coverage: {
        producedFromRealSdk: [
            "parseAgentFrontmatter (default options)",
            "loadAgentFiles (default options)",
            "buildCompatSessionConfigFragment(undefined)",
            "inheritsAppDefaults",
            "SessionManager._resolveTools",
        ],
        notCovered: [
            "The Set-union literal at session-manager.ts:954-959 is inlined in _getOrCreateUnlocked, which needs a live Copilot client and store; its inputs and its output ordering are covered here, the expression itself is not.",
        ],
    },
    parsedFrontmatter,
    loadedAgents,
    serializedSessionConfig,
    serializedSessionConfigKeys: Object.keys(serializedSessionConfig),
    toolResolution: {
        frameworkDefaultToolNames,
        appDefaultToolNames,
        agentDeclaredToolNames,
        appDefaultsInherited,
        inheritedToolNames,
        resolvedToolNamesInOrder,
    },
};

fs.writeFileSync(artifactPath, `${JSON.stringify(artifact, null, 4)}\n`, "utf-8");
console.log(`Wrote ${artifactPath}`);
